<template>
  <section class="flex flex-col gap-6">
    <UsersListHeader>
      <UsersListFilters :params="params" />
    </UsersListHeader>
    <Card>
      <AppLoader v-if="isLoading" subject="users" variant="inline" />
      <AppError v-else-if="error" :error="error" title="Failed to load users list" variant="table" />
      <ResponsiveTable v-else-if="data && data.items.length > 0" rounded>
        <ResponsiveTableHeader>
          <ResponsiveTableHead
            v-for="value in tableHead"
            :key="value"
            class="text-accent-foreground font-normal capitalize"
          >
            {{ value }}
          </ResponsiveTableHead>
        </ResponsiveTableHeader>
        <ResponsiveTableBody>
          <ResponsiveTableRow
            v-for="user in data.items"
            :key="user.id"
            :to="{ name: 'users-id', params: { id: user.id } }"
          >
            <ResponsiveTableCell :cols="4" :cols-sm="4" label="Name">
              <div class="text-base flex items-center gap-2">
                <AvatarImageWrapper
                  :src="user.profile_picture_url || ''"
                  alt="ProfilePic"
                  :fallback="`${user.first_name.charAt(0)}${user.last_name.charAt(0)}`"
                  size="sm"
                />
                <UserNameWithCompany :user="user" />
              </div>
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="4" :cols-sm="4" label="Email">
              <p class="text-base line-clamp-1 text-wrap break-all whitespace-normal">{{ user.email }}</p>
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="4" :cols-sm="4" label="Phone">
              <p class="text-base line-clamp-1">{{ user.phone }}</p>
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="2" :cols-sm="2" label="Role">
              <Badge variant="default">{{ getUserRole(user.role).name }}</Badge>
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="2" :cols-sm="2" label="Status">
              <Badge :variant="getUserStatus(user.status).variant">
                {{ getUserStatus(user.status).name }}
              </Badge>
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="4" :cols-sm="4" label="Onboarding State">
              <OnboardingState
                v-if="user.onboarding_state && (user.role === 'canvasser' || user.role === 'subcontractor_canvasser')"
                :onboarding-state="user.onboarding_state"
              />
            </ResponsiveTableCell>
          </ResponsiveTableRow>
        </ResponsiveTableBody>
        <ResponsiveTableFooter :colspan="6" :cols="4" :cols-sm="4">
          <AppPagination :page="queryParams.page" :size="queryParams.size" :total="data.total_count" label="users" />
        </ResponsiveTableFooter>
      </ResponsiveTable>
      <AppEmpty v-else subject="users" variant="table" />
    </Card>
  </section>
</template>

<script setup lang="ts">
import { getUserList } from '~/client';
import type {
  UserSortBy,
  SortType,
  UserRole,
  UserStatus,
  GetUserListResponse,
  UsersListRequest,
  CheckrSummaryStatus,
  UserSimilarityCheckStatus,
  RegisteredParty,
} from '~/client';
import { getUserRole } from '~/constants/users/userRoles';
import { getUserStatus } from '~/constants/users/userStatuses';

const route = useRoute('users');

definePageMeta({
  roles: ['admin'],
  backLabel: 'users',
});

useHead({
  title: 'Users',
});

const tableHead = ['name', 'email', 'phone', 'role', 'status', 'onboarding state'];

const queryParams = computed(() => {
  const { subcontractor_company_ids, include_unassigned } = parseSubcontractorCompanyFilter(
    route.query.subcontractor_company_ids
  );
  return {
    user_similarity_check_statuses: processArrayQueryParameterFromUrl<UserSimilarityCheckStatus>(
      route.query.user_similarity_check_statuses
    ),
    checkr_statuses: processArrayQueryParameterFromUrl<CheckrSummaryStatus>(route.query.checkr_statuses),
    ...parsePagination(route.query),
    sort_type: (route.query.sort_type || 'asc') as SortType,
    sort_by: (route.query.sort_by || 'name') as UserSortBy,
    search_query: (route.query.search_query as string) || undefined,
    roles: processArrayQueryParameterFromUrl<UserRole>(useRoute('users').query.roles),
    statuses: processArrayQueryParameterFromUrl<UserStatus>(useRoute('users').query.statuses),
    registered_parties: processArrayQueryParameterFromUrl<RegisteredParty>(route.query.registered_parties),
    subcontractor_company_ids,
    include_unassigned,
    onboarding_state: serializeOnboardingStateForKey(route.query),
  };
});

const params = computed<UsersListRequest>(() => {
  return {
    ...queryParams.value,
    onboarding_state: parseOnboardingStateFromQuery(route.query),
  };
});

const { data, error, isLoading } = useQuery({
  key: () => ['users-list', queryParams.value],
  query: (): Promise<GetUserListResponse> => {
    return getUserList({
      composable: '$fetch',
      body: params,
    });
  },
  staleTime: 0,
  enabled: () => route.name === 'users',
});

onBeforeMount(async () => {
  if (!params.value.statuses || params.value.statuses.length === 0) {
    await navigateTo(
      {
        name: 'users',
        query: {
          ...route.query,
          statuses: ['active'],
        },
      },
      { replace: true }
    );
  }
});
</script>

<style scoped lang="scss"></style>
